// test/features/hadith/hadith_hotfix_hr22_pair_parity_test.dart
// ============================================================
// HOTFIX HR-2.2 — the Urdu pair rescue, pinned where it is executed.
//
// The owner's order, in the mandatory order it was given: (a) the parity table
// FIRST, committed before any code change; (b) then the join change; (c) then the
// re-pins, with the English join and the 36,390-row spine pin untouched. § (a)
// lives in docs/HADITH_HR_PASS_REPORT.md and is generated by
// scripts/hr22_pairkey_parity.py. THIS file is what makes that table stay true:
// a report is prose, and prose does not fail when the code moves.
//
// The rule under test is ONE line of intent: the number-key text keeps its place
// whenever it is non-blank, and the pair index is consulted ONLY to rescue a blank
// or a missing hit. +52 rows of Urdu, 0 existing texts blanked, 0 re-attributed.
//
// What each test is for:
//   1. the app's own `assembleHadithBook`, over all 36,390 real spine rows, joined
//      exactly as the rescue rule joins — no mirror number in this file is allowed
//      to disagree with what the shipped code produces;
//   2. the effect counts (52 recovered, 0 blanked, 0 re-attributed) and the coverage
//      move (33,424 -> 33,476 = 91.99 %, neither-rows 206 -> 203), asserted against
//      the ASSEMBLED rows, not against a re-derivation;
//   3. the recovery's proof of identity: every recovered row's Urdu record carries
//      the same `reference` as the English row it lands on — a third key neither
//      join uses, so "recovered" cannot quietly mean "guessed";
//   4. WHY the rescue never overrides: malik's and muslim's Urdu files do not share
//      the English file's numbering space (measured, 631/1,858 and 0/7,563);
//   5. the rejected alternative, pinned by its cost: a pure pair re-key blanks 9
//      rows and re-attributes 28 — if anyone "simplifies" the rescue into an
//      override, this goes red with the counts in the failure message;
//   6. the join exists ONCE (source pins): the assembler is the only Urdu join for
//      main and the worker alike, and the English arm is byte-identical to the
//      line HR-2.1 shipped.
//
// Red evidence (written in a sandbox with no Dart SDK — CI is the only compiler).
// Against `4c1ac80` (the § (a) commit: script + report, zero code) this file is red
// on tests 1, 2 and 6: the assembler still joins by the floored int key only, so
// `textUrdu` disagrees on exactly the 52 rescue rows, the count is 33,424 not
// 33,476, and `urduJoinText` does not exist yet for the source pin to find. Run IDs
// and the actual analyzer list is recorded in
// docs/HADITH_HR_PASS_REPORT.md § HR-2.2 (b).
//
// Conventions match hadith_hotfix_hr21_coverage_census_test / hadith_pass_x6_test:
// public runtime helpers where a rule is testable, source pins where the bug class
// is grep-visible, every number measured from the shipped files.
// ============================================================

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:qibra_ai/features/hadith/data/hadith_availability.dart';
import 'package:qibra_ai/features/hadith/data/services/hadith_database_service.dart';

import '../../support/source_guards.dart';

const List<String> _books = [
  'bukhari',
  'muslim',
  'abudawud',
  'nasai',
  'ibnmajah',
  'malik',
  'tirmidhi',
];

const String _dir = 'assets/data/hadith';

final Map<String, Map<String, dynamic>> _json = {};

Map<String, dynamic> _bookJson(String slug, String edition) =>
    _json.putIfAbsent(
      '$slug/$edition',
      () => jsonDecode(File('$_dir/$slug/$edition.json').readAsStringSync())
          as Map<String, dynamic>,
    );

List<Map<String, dynamic>> _rows(String slug, String edition) =>
    (_bookJson(slug, edition)['hadiths'] as List<dynamic>)
        .cast<Map<String, dynamic>>();

/// The loader's tolerant `hadithnumber` parse (`_parseHadithNumber`), mirrored
/// exactly as `hadith_hotfix_hr21_coverage_census_test` mirrors it: leading
/// digits of any scalar, else 0. Pinned there, so this file inherits the proof.
int _intKey(dynamic v) {
  if (v is num) return v.toInt();
  final m = RegExp(r'^(\d+)').firstMatch((v ?? '').toString());
  return m == null ? 0 : (int.tryParse(m.group(1)!) ?? 0);
}

String _text(Map<String, dynamic> row) => '${row['text'] ?? ''}';

/// A row's `reference` as ONE comparable string. Needed because `Map ==` in Dart is
/// identity: two decoded `{book, hadith}` maps with the same content are not equal,
/// so a structural comparison written with `==` on maps measures zero and looks
/// like a data bug. `reference` carries exactly these two keys in all 14 files
/// (measured), so this string is the whole record.
String _refKey(Map<String, dynamic> row) {
  final ref = row['reference'];
  return ref is Map<String, dynamic> ? '${ref['book']}:${ref['hadith']}' : '';
}

/// The OLD map, byte-for-byte the loop `assembleHadithBook` has run since before
/// X5: floored int key, LAST write wins, a blank row overwrites a real one.
Map<int, String> _numberMap(String slug) {
  final out = <int, String>{};
  for (final row in _rows(slug, 'urdu')) {
    out[_intKey(row['hadithnumber'])] = _text(row);
  }
  return out;
}

/// The rescue, expressed with the service's OWN pair index (the same function the
/// four Phase-B languages go through) so this file cannot drift from the rule.
Map<String, String> _pairMap(String slug) =>
    HadithDatabaseService.pairTextIndex(_rows(slug, 'urdu'));

/// `reference` as a STRING, per pair key — the record identity the pair index
/// selects, kept so test 3 can prove what it joined.
Map<String, String> _pairRef(String slug) {
  final out = <String, String>{};
  for (final row in _rows(slug, 'urdu')) {
    final text = _text(row);
    if (text.trim().isEmpty) continue;
    out.putIfAbsent(
      HadithDatabaseService.pairKey(row['hadithnumber'], row['arabicnumber']),
      () => _refKey(row),
    );
  }
  return out;
}

String _rescue(String byNumber, String byPair) =>
    byNumber.trim().isEmpty && byPair.isNotEmpty ? byPair : byNumber;

/// One book, as the shipped code assembles it — the real function, real files,
/// cached so the seven tests below pay the decode once.
final Map<String, List<LocalHadith>> _assembled = {};

List<LocalHadith> _assembleBook(String slug) => _assembled.putIfAbsent(slug, () {
      final out = assembleHadithBook(
        englishData: _bookJson(slug, 'english'),
        urduData: _bookJson(slug, 'urdu'),
        langIndices: const <String, Map<String, String>>{},
        slug: slug,
        name: slug,
      );
      expect(out, isNotNull, reason: '$slug assembles to nothing');
      return out!.hadiths;
    });

void main() {
  group('HR-2.2 the Urdu pair rescue', () {
    test('the app joins EXACTLY the rescue rule, every spine row of every book',
        () {
      var compared = 0, mismatches = 0;
      final mismatch = <String>[];
      for (final slug in _books) {
        final byNumber = _numberMap(slug);
        final byPair = _pairMap(slug);
        final spine = _rows(slug, 'english');
        final rows = _assembleBook(slug);
        expect(rows.length, spine.length, reason: '$slug lost or gained a row');
        for (var i = 0; i < spine.length; i++) {
          final row = spine[i];
          final expected = _rescue(
            byNumber[_intKey(row['hadithnumber'])] ?? '',
            byPair[HadithDatabaseService.pairKey(
              row['hadithnumber'],
              row['arabicnumber'],
            )] ??
                '',
          );
          compared++;
          if (rows[i].textUrdu != expected) {
            mismatches++;
            if (mismatch.length < 5) {
              mismatch.add('$slug #$i hadithnumber=${row['hadithnumber']}');
            }
          }
        }
      }
      expect(compared, 36390, reason: 'the spine this pass measured is 36,390 rows');
      expect(mismatches, 0,
          reason: '$mismatches of $compared rows disagree — and that disagreement IS '
              'HR-2.2: the app must implement the rule this file measures, not the '
              'other way round. First five: ${mismatch.join(', ')}');
    }, timeout: const Timeout(Duration(minutes: 8)));

    test('+52 recovered, 0 blanked, 0 re-attributed — measured against the app',
        () {
      var recovered = 0, blanked = 0, changed = 0;
      for (final slug in _books) {
        final byNumber = _numberMap(slug);
        final byPair = _pairMap(slug);
        final spine = _rows(slug, 'english');
        final rows = _assembleBook(slug);
        for (var i = 0; i < spine.length; i++) {
          final row = spine[i];
          final old = byNumber[_intKey(row['hadithnumber'])] ?? '';
          final pair = byPair[HadithDatabaseService.pairKey(
                row['hadithnumber'],
                row['arabicnumber'],
              )] ??
              '';
          final shipped = rows[i].textUrdu;
          if (old.trim().isEmpty && shipped.trim().isNotEmpty) recovered++;
          if (old.trim().isNotEmpty && shipped.trim().isEmpty) blanked++;
          if (old.trim().isNotEmpty &&
              shipped.trim().isNotEmpty &&
              old != shipped) {
            changed++;
          }
          if (old.trim().isNotEmpty && pair.trim().isEmpty &&
              shipped != old) {
            fail('$slug #$i: a row the number key already resolved moved anyway');
          }
        }
      }
      expect(recovered, 52,
          reason: 'the exact § (a) count: bukhari 25, tirmidhi 24, ibnmajah 2, '
              'nasai 1');
      expect(blanked, 0,
          reason: 'HR-2.2 may not blank a text the reader already had — that is '
              'the gate the owner set, and the reason the pair index rescues '
              'instead of overriding');
      expect(changed, 0, reason: 'and may not re-attribute one either');
    }, timeout: const Timeout(Duration(minutes: 8)));

    test('coverage old -> new: 33,424 to 33,476 urdu rows, 206 to 203 with neither',
        () {
      var urdu = 0, english = 0, neither = 0;
      final perBook = <String, int>{};
      for (final slug in _books) {
        var bookUrdu = 0;
        final rows = _assembleBook(slug);
        for (final row in rows) {
          final hasEn = row.textEnglish.trim().isNotEmpty;
          final hasUr = row.textUrdu.trim().isNotEmpty;
          if (hasEn) english++;
          if (hasUr) {
            urdu++;
            bookUrdu++;
          }
          if (!hasEn && !hasUr) neither++;
        }
        perBook[slug] = bookUrdu;
      }
      expect(english, 35975, reason: 'the English join is UNTOUCHED by this pass');
      expect(urdu, 33476, reason: '33,424 + 52, and nothing else');
      expect(neither, 203, reason: '206 - 3: the three tirmidhi rows that had '
          'nothing at all now have Urdu');
      // The reader is never shown a whole-corpus number — the disclosure line is
      // per book — so the per-book percents are what must not move, through the
      // app's OWN rounding (rounded, not floored, `HadithAvailability.coveragePercent`).
      for (final e in perBook.entries) {
        expect(HadithAvailability.coveragePercent(e.value, _rows(e.key, 'english').length),
            {
              'bukhari': 92,
              'muslim': 99,
              'abudawud': 100,
              'nasai': 67,
              'ibnmajah': 100,
              'malik': 86,
              'tirmidhi': 98,
            }[e.key],
            reason: '${e.key}/urdu keeps the percent the HR-2.1 § C table printed — '
                'HR-2.2 moves counts, not what the reader sees');
      }
      expect(perBook, {
        'bukhari': 7019,
        'muslim': 7458,
        'abudawud': 5273,
        'nasai': 3876,
        'ibnmajah': 4329,
        'malik': 1590,
        'tirmidhi': 3931,
      });
    }, timeout: const Timeout(Duration(minutes: 8)));

    test('every recovered row is the SAME hadith, proved by a key neither join uses',
        () {
      var verified = 0;
      final unproven = <String>[];
      for (final slug in _books) {
        final byNumber = _numberMap(slug);
        final refs = _pairRef(slug);
        final spine = _rows(slug, 'english');
        final rows = _assembleBook(slug);
        for (var i = 0; i < spine.length; i++) {
          final row = spine[i];
          final hadTextBefore =
              (byNumber[_intKey(row['hadithnumber'])] ?? '').trim().isNotEmpty;
          if (hadTextBefore || rows[i].textUrdu.trim().isEmpty) continue;
          verified++;
          final pair = HadithDatabaseService.pairKey(
            row['hadithnumber'],
            row['arabicnumber'],
          );
          final expected = _refKey(row);
          if (refs[pair] != expected) {
            unproven.add('$slug #$i joined $expected onto ${refs[pair]}');
          }
        }
      }
      expect(verified, 52, reason: 'one recovery per row listed in § (a)');
      expect(unproven, isEmpty,
          reason: 'a recovery whose Urdu record points at a different '
              'book:hadith is a mis-join, not a gain (${unproven.join(', ')})');
    }, timeout: const Timeout(Duration(minutes: 8)));

    test('why no override: two books do not share the English numbering space', () {
      for (final slug in _books) {
        final spine = _rows(slug, 'english');
        final urdu = _rows(slug, 'urdu');
        var numAgree = 0, refAgree = 0;
        final n = spine.length < urdu.length ? spine.length : urdu.length;
        for (var i = 0; i < n; i++) {
          if (spine[i]['hadithnumber'] == urdu[i]['hadithnumber']) numAgree++;
          if (_refKey(spine[i]) == _refKey(urdu[i])) refAgree++;
        }
        if (slug == 'malik') {
          // 1,889 Urdu records for a 1,858-row spine, agreeing on a third of it: a
          // pair hit here is not evidence the text belongs to the row.
          expect(urdu.length, 1889);
          expect(numAgree, 631);
          expect(refAgree, 644);
        } else if (slug == 'muslim') {
          // Numbered in a different space entirely — index-level agreement is nil,
          // yet the value join resolves 7,458 of 7,563 rows.
          expect(numAgree, 0);
          expect(refAgree, 127);
        } else {
          expect(numAgree, n, reason: '$slug: the two files are index-aligned');
          expect(refAgree, n, reason: '$slug: and reference-aligned');
        }
      }
    });

    test('the rejected alternative, priced: a pure re-key blanks 9 and re-attributes 28',
        () {
      var pureBlanked = 0, pureChanged = 0, pureRecovered = 0;
      final perBook = <String, int>{};
      for (final slug in _books) {
        final byNumber = _numberMap(slug);
        final byPair = _pairMap(slug);
        var blanked = 0, changed = 0;
        for (final row in _rows(slug, 'english')) {
          final old = byNumber[_intKey(row['hadithnumber'])] ?? '';
          final pair = byPair[HadithDatabaseService.pairKey(
                row['hadithnumber'],
                row['arabicnumber'],
              )] ??
              '';
          if (old.trim().isNotEmpty && pair.trim().isEmpty) blanked++;
          if (old.trim().isNotEmpty &&
              pair.trim().isNotEmpty &&
              old != pair) {
            changed++;
          }
          if (old.trim().isEmpty && pair.trim().isNotEmpty) pureRecovered++;
        }
        pureBlanked += blanked;
        pureChanged += changed;
        perBook[slug] = blanked * 1000 + changed;
      }
      expect(pureRecovered, 52,
          reason: 'the rescue and the override find the same 52 rows — the rescue '
              'just refuses to pay for them');
      expect(pureBlanked, 9, reason: 'malik 7, nasai 2, every one listed in § (a)');
      expect(pureChanged, 28, reason: 'malik 24, nasai 3, tirmidhi 1');
      expect(perBook['malik'], 7 * 1000 + 24);
      expect(perBook['nasai'], 2 * 1000 + 3);
    });

    test('the join exists once, in the function main and the worker share', () {
      final service =
          _src('lib/features/hadith/data/services/hadith_database_service.dart');
      final worker =
          _src('lib/features/hadith/data/services/hadith_search_worker.dart');
      final code = stripCommentsForGuard(service);
      final workerCode = stripCommentsForGuard(worker);

      // The rule is a named function, and the assembler is its only caller in the
      // shipped path — a second call site would be a second join.
      expect(code.contains('static String urduJoinText('), isTrue,
          reason: 'the rescue rule is a named, testable function on the service, '
              'not an expression inside the row loop');
      expect(code.contains('textUrdu: HadithDatabaseService.urduJoinText('), isTrue,
          reason: 'the assembler joins through it');
      expect('urduJoinText('.allMatches(code).length, 2,
          reason: 'declaration + the one call site. A third is a second '
              'implementation of the join, which is the bug class this family keeps '
              'naming in its own docs');
      // And the Urdu pair index is built once per book, from the file's rows.
      expect(code.contains('pairTextIndex(urduHadiths)'), isTrue);
      expect('pairTextIndex('.allMatches(code).length, 3,
          reason: 'exactly three: the declaration, the Phase-B language index in '
              '_loadLanguageIndex, and the Urdu rescue. A fourth is a second fold '
              'of the same file');

      // The worker assembles through the SAME function, so it needs no join of its
      // own; that is verified here, not assumed.
      expect(workerCode.contains('assembleHadithBook('), isTrue);
      expect('urduJoinText('.allMatches(workerCode).length, 0,
          reason: 'the worker has no Urdu join to keep in sync — it calls the '
              'assembler, exactly as HR-1 established');
      expect('<int, String>'.allMatches(workerCode).length, 0,
          reason: 'no int-keyed Urdu map in the worker: one map, one place');

      // The English arm is byte-identical to the line HR-2.1 shipped.
      expect(code.contains("textEnglish: map['text']?.toString() ?? '',"), isTrue,
          reason: 'HR-2.2 touches Urdu only');
      expect(code.contains("final baseData = englishData ?? urduData;"), isTrue,
          reason: 'the spine is still the English list, so the 36,390-row no-row-lost '
              'proof of HR-2.1 § C still means what it said');
    });
  });
}

/// Source text of a repo file — the same read the guards in the sibling tests do.
String _src(String path) => File(path).readAsStringSync();
